# Import of required libraries
import skyramp
import os
import time


from SkyrampUtils import (
    create_flow,
    create_flow_run,
    create_work_pool,
    create_work_queue,
    get_work_queue_stats,
)


def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    # Definition of authentication header
    headers = {}
    if os.getenv("SKYRAMP_TEST_TOKEN") is not None:
        headers["X-Admin-Key"] = os.getenv("SKYRAMP_TEST_TOKEN")

    endpoint_3_POST_response = create_work_pool(
        client, headers, skyramp.unique_suffix("tb-stats-pool-1")
    )

    assert skyramp.get_response_value(endpoint_3_POST_response, "type") == "process"

    queues_POST_response = create_work_queue(
        client,
        headers,
        skyramp.get_response_value(endpoint_3_POST_response, "name"),
        skyramp.unique_suffix("tb-stats-queue-1"),
    )

    assert skyramp.get_response_value(
        queues_POST_response, "work_pool_name"
    ) == skyramp.get_response_value(endpoint_3_POST_response, "name")
    assert skyramp.check_schema(queues_POST_response, '{"stats": null}')

    endpoint_2_POST_response = create_flow(
        client, headers, skyramp.unique_suffix("tb-stats-flow-1")
    )

    # Request Body
    endpoint_1_POST_request_body = r'''{
        "flow_id": "c93f5a10-2b47-4e8d-8a16-5f0d9c2e4187",
        "state": {
            "state_details": {
                "scheduled_time": "2027-01-01T00:00:00Z"
            },
            "type": "SCHEDULED"
        },
        "work_pool_name": "tb-stats-pool-1",
        "work_queue_name": "tb-stats-queue-1"
    }'''

    endpoint_1_POST_response = create_flow_run(
        client,
        headers,
        endpoint_1_POST_request_body,
        {
            "flow_id": skyramp.get_response_value(endpoint_2_POST_response, "id"),
            "work_pool_name": skyramp.get_response_value(queues_POST_response, "work_pool_name"),
            "work_queue_name": skyramp.get_response_value(queues_POST_response, "name"),
        },
    )

    assert skyramp.get_response_value(
        endpoint_1_POST_response, "flow_id"
    ) == skyramp.get_response_value(endpoint_2_POST_response, "id")
    assert skyramp.get_response_value(
        endpoint_1_POST_response, "work_queue_name"
    ) == skyramp.get_response_value(queues_POST_response, "name")
    assert skyramp.get_response_value(
        endpoint_1_POST_response, "work_queue_id"
    ) == skyramp.get_response_value(queues_POST_response, "id")
    assert skyramp.get_response_value(endpoint_1_POST_response, "state.type") == "SCHEDULED"

    # Request Body
    endpoint_1_POST_1_request_body = r'''{
        "flow_id": "c93f5a10-2b47-4e8d-8a16-5f0d9c2e4187",
        "state": {
            "state_details": {
                "scheduled_time": "2027-01-01T00:00:00Z"
            },
            "type": "SCHEDULED"
        },
        "work_queue_name": "tb-stats-queue-1"
    }'''

    endpoint_1_POST_1_response = create_flow_run(
        client,
        headers,
        endpoint_1_POST_1_request_body,
        {
            "flow_id": skyramp.get_response_value(endpoint_2_POST_response, "id"),
            "work_queue_name": skyramp.get_response_value(queues_POST_response, "name"),
        },
    )

    assert skyramp.get_response_value(
        endpoint_1_POST_1_response, "flow_id"
    ) == skyramp.get_response_value(endpoint_2_POST_response, "id")
    assert skyramp.get_response_value(
        endpoint_1_POST_1_response, "work_queue_name"
    ) == skyramp.get_response_value(queues_POST_response, "name")
    assert skyramp.get_response_value(endpoint_1_POST_1_response, "state.type") == "SCHEDULED"
    assert skyramp.check_schema(endpoint_1_POST_1_response, '{"work_queue_id": null}')

    stats_GET_response = get_work_queue_stats(
        client, headers, skyramp.get_response_value(queues_POST_response, "id")
    )

    assert skyramp.check_schema(
        stats_GET_response, '{"running": 0, "pending": 0, "scheduled_count": 0}'
    )
    assert int(skyramp.get_response_value(stats_GET_response, "running")) == 0
    assert int(skyramp.get_response_value(stats_GET_response, "pending")) == 0
    assert int(skyramp.get_response_value(stats_GET_response, "scheduled_count")) == 2


if __name__ == "__main__":
    test_integration()
